assert set(KEN) == set(S.KINDS) and len(KEN) == 20, set(S.KINDS) ^ set(KEN)
def RNG(r):
    c, vv = r.split(':'); parts = vv.split('-'); return int(c), int(parts[0]), int(parts[-1])
KINDS = []
for kind, first, rng, claim, cell, form, fields, effs, reuses in S.LINES:
    c, lo, hi = RNG(rng); en, he_en, extra, speaker, tape = KEN[kind]
    KINDS.append((kind, form, en, HE(D, c, lo, hi, he_en), WIT(D, c, lo, hi) + [w for ws in extra for w in ws], INK, CORPUS, SUB % (speaker, tape), fields))
OWN20 = [k[0] for k in KINDS]
assert len(KINDS) == 20 and OWN20 == S.KINDS and all(len(k[8]) >= 2 for k in KINDS)
assert [k[1] for k in KINDS].count('statute') == 13 and [k[1] for k in KINDS].count('act') == 4 and [k[1] for k in KINDS].count('speech') == 3
path = f"{ROOT}/World/step9/event_vocabulary.yaml"
text = open(path, encoding='utf-8').read()
have = yaml.safe_load(text)['events']
HOLEK = sorted(k for k in have if k in OWN20)
NEARK = sorted(k for k in have if k not in OWN20 and any(t in k for t in ('moab', 'covenant_oath', 'idolater', 'desolation', 'hidden', 'return_and', 'circumcis', 'commandment_near', 'life_and_death', 'crossing_charge', 'joshua_charged', 'law_written', 'hakhel', 'tent_summons', 'apostasy', 'song_', 'joshua_commission', 'beside_the_ark', 'assembly_and')))
print('the registry\'s kinds among the twenty before this sitting:', HOLEK, '| the near kinds on file (not ours):', NEARK)
assert HOLEK == [] or HOLEK == sorted(OWN20), HOLEK   # the twenty kinds absent before this sitting — or this sitting's own, written by the first run (idempotent)
out = []
for name, form, en, he, wit, ink, corpus, tape, fields in KINDS:
    if name in have: continue
    out.append(f"  {name}:\n    en: {q(en)}\n    he: {q(he)}\n    form: {form}\n    witness: [{', '.join(q(w) for w in wit)}]\n    ink: {q(ink)}\n    corpus: {q(corpus)}\n    tape: {q(tape)}\n    fields: [{', '.join(q(f) for f in fields)}]\n")
if out and not CHECK:
    i = text.index('\nnarrative_verbs:\n')
    text = text[:i] + '\n' + ''.join(out).rstrip('\n') + text[i:]
    open(path, 'w', encoding='utf-8').write(text)
after = yaml.safe_load(open(path, encoding='utf-8'))
assert CHECK or all(k[0] in after['events'] for k in KINDS)
print('kinds: %d %s of %d (13 statute / 4 act / 3 speech), registry %d; the ledger sources %d (%d excluded -> %d), Onkelos %d, the spine %d, outside %d rows in piskaot %s' % (len(out), 'to add' if CHECK else 'added', len(KINDS), len(after['events']), N_SRC, N_EX, N_SRC - N_EX, N_ONK, N_SPINE, N_OUT, OUTSIDE))
